#!/usr/bin/env python3
"""Every ignored test (JUnit 4 @Ignore, JUnit 5 @Disabled) must say why.

    python3 .github/scripts/ignored_tests.py            # exit 1 and list the ignores that give no reason
    python3 .github/scripts/ignored_tests.py --markdown # the current list as a markdown table (docs/revival/IGNORED_TESTS.md)

A reason is the annotation's text (@Ignore("why")) or a comment on the line(s) right above or below the annotation.
Python 3 standard library only; reads the files git tracks.
"""
import re, subprocess, sys

ANNOTATION = re.compile(r'^\s*@(Ignore|Disabled)\b(.*)$')
COMMENT = re.compile(r'^\s*(//|/\*|\*)')
TARGET = re.compile(r'\b(?:void|class)\s+(\w+)')


def ignores():
    """[(path, line, target, reason or None)] for every @Ignore / @Disabled in tracked Java files."""
    files = subprocess.run(["git", "ls-files", "*.java"], capture_output=True, text=True, check=True).stdout.split()
    out = []
    for path in files:
        with open(path, encoding="utf-8", errors="replace") as f:
            lines = f.read().split("\n")
        for i, line in enumerate(lines):
            m = ANNOTATION.match(line)
            if not m:
                continue
            text = re.search(r'\(\s*(?:value\s*=\s*)?"(.+)"', m.group(2))
            reason = text.group(1) if text else None
            if not reason:  # a comment just above (or just below) the annotation
                near = [lines[j].strip() for j in (i - 1, i + 1) if 0 <= j < len(lines) and COMMENT.match(lines[j])]
                reason = " ".join(c.lstrip("/*").strip() for c in near if c.lstrip("/*").strip()) or None
            target = next((t.group(1) for t in map(TARGET.search, lines[i + 1:i + 8]) if t), "?")
            out.append((path, i + 1, target, reason))
    return out


def main(argv):
    found = ignores()
    if "--markdown" in argv:
        print(f"{len(found)} ignored tests (generated by `.github/scripts/ignored_tests.py --markdown`).\n")
        print("| Module | Test | Reason |\n|---|---|---|")
        for path, line, target, reason in found:
            module = path.split("/src/")[0]
            cls = path.rsplit("/", 1)[1][:-5]
            test = cls if target == cls else f"{cls}.{target}"
            print(f"| {module} | [{test}]({'../../' + path}#L{line}) | {(reason or '**no reason given**').replace('|', '/')} |")
        return 0
    missing = [x for x in found if not x[3]]
    for path, line, target, _ in missing:
        print(f"{path}:{line}: @Ignore on {target} gives no reason: write @Ignore(\"why\")")
    print(f"{len(found)} ignored tests, {len(missing)} without a reason")
    return 1 if missing else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))
